// These tests live in-crate (rather than under tests/) because `HeaderSelector`
// and its module are crate-private (internal content-negotiation detail) and so
// are not reachable from the external integration-test crate.
#[cfg(test)]
mod tests {
    use super::HeaderSelector;

    #[test]
    fn test_header_selector_is_json_mime() {
        let hs = HeaderSelector::new();

        assert!(hs.is_json_mime("application/json"));
        assert!(hs.is_json_mime("application/json; charset=utf-8"));
        assert!(hs.is_json_mime("application/vnd.api+json"));
        assert!(!hs.is_json_mime("application/xml"));
        assert!(!hs.is_json_mime("text/plain"));
        assert!(!hs.is_json_mime(""));
        assert!(!hs.is_json_mime("application/octet-stream"));
        assert!(hs.is_json_mime("application/hal+json"));
    }

    #[test]
    fn test_header_selector_select_headers_with_single_accept() {
        let hs = HeaderSelector::new();

        let headers = hs.select_headers(&["application/json"], "application/json", false);

        assert_eq!(headers.get("Accept").unwrap(), "application/json");
        assert_eq!(headers.get("Content-Type").unwrap(), "application/json");
    }

    #[test]
    fn test_header_selector_select_headers_with_multiple_accepts() {
        let hs = HeaderSelector::new();

        let headers = hs.select_headers(
            &["application/json", "application/xml"],
            "application/json",
            false,
        );

        let accept = headers.get("Accept").unwrap();
        assert!(accept.contains("application/json"));
    }

    #[test]
    fn test_header_selector_select_headers_with_empty_accepts() {
        let hs = HeaderSelector::new();

        let headers = hs.select_headers(&[], "application/json", false);

        assert!(!headers.contains_key("Accept"));
    }

    #[test]
    fn test_header_selector_multipart_omits_content_type() {
        let hs = HeaderSelector::new();

        let headers = hs.select_headers(&["application/json"], "multipart/form-data", true);

        assert!(
            !headers.contains_key("Content-Type"),
            "expected no Content-Type header for multipart requests"
        );
    }

    #[test]
    fn test_header_selector_default_content_type() {
        let hs = HeaderSelector::new();

        let headers = hs.select_headers(&["application/json"], "", false);

        assert_eq!(headers.get("Content-Type").unwrap(), "application/json");
    }

    #[test]
    fn test_header_selector_joins_in_declaration_order() {
        let hs = HeaderSelector::new();

        let headers = hs.select_headers(
            &["image/jpeg", "image/png", "application/json"],
            "application/json",
            false,
        );

        assert_eq!(
            headers.get("Accept").unwrap(),
            "image/jpeg, image/png, application/json"
        );
    }

    #[test]
    fn test_header_selector_single_element() {
        let hs = HeaderSelector::new();

        let headers = hs.select_headers(&["application/json"], "application/json", false);

        assert_eq!(headers.get("Accept").unwrap(), "application/json");
    }

    #[test]
    fn test_header_selector_does_not_reorder_or_weight() {
        let hs = HeaderSelector::new();

        let headers = hs.select_headers(
            &["text/html", "application/vnd.api+json", "application/json"],
            "application/json",
            false,
        );

        assert_eq!(
            headers.get("Accept").unwrap(),
            "text/html, application/vnd.api+json, application/json"
        );
    }

    #[test]
    fn test_header_selector_is_json_mime_case_insensitive() {
        let hs = HeaderSelector::new();

        assert!(hs.is_json_mime("APPLICATION/JSON"));
    }

    #[test]
    fn test_header_selector_single_non_json_accept_as_is() {
        let hs = HeaderSelector::new();

        let headers = hs.select_headers(&["text/html"], "application/json", false);

        assert_eq!(headers.get("Accept").unwrap(), "text/html");
    }

    #[test]
    fn test_header_selector_comma_space_separated() {
        let hs = HeaderSelector::new();

        let headers = hs.select_headers(&["text/html", "text/plain"], "application/json", false);

        assert_eq!(headers.get("Accept").unwrap(), "text/html, text/plain");
    }

    #[test]
    fn test_header_selector_filters_out_empty_entries() {
        let hs = HeaderSelector::new();

        let headers = hs.select_headers(
            &["", "application/json", "", "application/xml"],
            "application/json",
            false,
        );

        assert_eq!(
            headers.get("Accept").unwrap(),
            "application/json, application/xml"
        );
    }

    #[test]
    fn test_header_selector_all_empty_omits_accept() {
        let hs = HeaderSelector::new();

        let headers = hs.select_headers(&["", ""], "application/json", false);

        assert!(!headers.contains_key("Accept"));
    }
}
